#include <bits/stdc++.h>
using namespace std;

struct InputData {
    long long m;
    int n, m_;
    bool read() {
        return !!(cin >> n >> m_ >> m);
    }
};

struct OutputData: InputData {
    long long answer;
    void print() {
        cout << answer << "\n";
    }
};

namespace SolverNamespace {
    struct Solution {
        long long pow_mod(long long base, long long exp) {
            long long res = 1;
            while (exp > 0) {
                if (exp & 1) res = res * base % m;
                base = base * base % m;
                exp >>= 1;
            }
            return res;
        }

        long long mod_inv(long long x) {
            return pow_mod(x, m - 2);
        }

        long long comb[504][504];

        pair<long long, long long> seq[505];
        pair<long long, long long> dp[505][505];

        void compute() {
            for (int i = 0; i <= n; ++i) {
                for (int j = 0; j <= n; ++j) {
                    if (i == 0 || j == 0) comb[i][j] = 1;
                    else comb[i][j] = (comb[i - 1][j] + comb[i][j - 1]) % m;
                }
            }

            fill_n(seq, m_ + 1, make_pair(0, 0));
            seq[0] = {1, 0};
            for (int i = 1; i <= m_; ++i) {
                for (int j = 0; j < i; ++j) {
                    pair<long long, long long> cur;
                    cur.first = seq[j].first * seq[i - 1 - j].first % m;
                    cur.second = (seq[j].second * seq[i - 1 - j].first + seq[j].first * seq[i - 1 - j].second) % m;
                    cur.second = (cur.second * (i + 1) + (ss(j) + ss(i - 1 - j)) * cur.first) % m;
                    cur.first = cur.first * (i + 1) % m;
                    cur.first = cur.first * comb[j][i - 1 - j] % m;
                    cur.second = cur.second * comb[j][i - 1 - j] % m;
                    seq[i].first = (seq[i].first + cur.first) % m;
                    seq[i].second = (seq[i].second + cur.second) % m;
                }
            }

            memset(dp, 0, sizeof dp);
            dp[0][0] = {1, 0};
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= m_; ++j) {
                    for (int k = 0; k <= min(n - i, m_ - j); ++k) {
                        pair<long long, long long> cur;
                        cur.first = seq[k].first * dp[i][j].first % m;
                        cur.second = (seq[k].second * dp[i][j].first + seq[k].first * dp[i][j].second) % m;
                        cur.first = cur.first * comb[j][k] % m;
                        cur.second = cur.second * comb[j][k] % m;
                        dp[i + k + 1][j + k].first = (dp[i + k + 1][j + k].first + cur.first) % m;
                        dp[i + k + 1][j + k].second = (dp[i + k + 1][j + k].second + cur.second) % m;
                    }
                }
            }
            answer = dp[n + 1][m_].second;
        }
        void reset() {
            *this = Solution();
        }
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    SolverNamespace::Solution sol;
    if (getenv("SG")) {
        freopen("problem.in", "r", stdin);
        while (sol.read()) {
            sol.compute();
            sol.print();
            sol.reset();
        }
    } else {
        sol.read();
        sol.compute();
        sol.print();
    }
    return 0;
}
